import {uid,createState,createMatch,validateState,activeEvents,addEvent,reviseEvent,removeEvent,summarize,clockMs,formatClock} from './core.mjs';
import {readState,writeState,downloadFile,backupEnvelope,parseBackup,csv} from './storage.mjs';
import {mountTactics} from './tactics.mjs';
import {dashboardModel,attackPhaseModel} from './dashboard.mjs';
import {mountReadiness} from './readiness.mjs';
import {mountPersonalReport} from './personal-report.mjs';
import {mountRecordFlow} from './record-flow.mjs';
import {TURNOVER_TYPES,eventDetailLabel,prepareTurnoverEvent,prepareRecordEdit} from './event-details.mjs';
import {mountVideo} from './video.mjs';
import {mountSync,startSync} from './sync.mjs';
import {mountAdvancedAnalysis} from './advanced-analysis.mjs';
import {workbookBlob,shareSnapshot,encodeShare,decodeShare} from './export.mjs';

const staticHosting=location.hostname.endsWith('.github.io');
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n==null?'—':`${n.toFixed(1)}%`;
const phaseNames={set:'セットOF',fast:'速攻',quick:'クイックスタート'};
const typeNames={seven_meter_awarded:'7m獲得',interception:'パスカット',loose_ball:'ルーズボール',free_throw_won:'FT獲得',free_throw_conceded:'FT被獲得',score_adjustment:'得点補正',shot:'シュート',turnover:'ミス',warning:'警告',suspension:'2分間退場',disqualification:'失格',timeout:'タイムアウト',substitution:'交代'};
const resultNames={goal:'得点',saved:'GKセーブ',miss:'枠外',post:'ポスト',blocked:'ブロック'};
const viewNames={dashboard:'ホーム',matches:'試合一覧',record:'試合記録',analysis:'データ分析',video:'動画分析',tactics:'作戦盤',roster:'チーム・選手',inventory:'備品管理',settings:'保存・共有'};
const symbols={dashboard:'◫',matches:'▤',record:'◉',analysis:'▥',video:'▷',tactics:'⌘',roster:'♙',inventory:'▣',settings:'⚙'};
let syncCleanup,fullWidth=false,ownOnly=false,videoClock=null,videoDock=false;
let pendingSaves=0;
let state,view='dashboard',matchId,teamId,cleanup,saveChain=Promise.resolve(),saveFailed=false,readonly=false;
let selection={},draft={},analysisTab='players',analysisScope='all',analysisTournament='',recordMode='guided',eventFilter='',undoStack=[];
const root=$('#app');
export function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function currentMatch(){return state.matches.find(m=>m.id===matchId);}
function team(id){return state.teams.find(t=>t.id===id);}
function player(id){for(const t of state.teams){const p=t.players.find(p=>p.id===id);if(p)return p;}return null;}
function playerLabel(id,m){const archived=m?Object.values(m.rosterSnapshots||{}).flat().find(p=>p.id===id):null;const p=archived||player(id);return p?`#${p.number} ${p.name}`:'選手未指定';}
function matchLabel(m){return m.name||`${team(m.homeTeamId)?.name||'自チーム'} vs ${team(m.awayTeamId)?.name||m.opponent}`;}
function replaceMatch(m){state.matches=state.matches.map(x=>x.id===m.id?m:x);}
async function save(){if(readonly)throw new Error('閲覧専用です');const snapshot=structuredClone(state);pendingSaves++;updateSaveBadge();saveChain=saveChain.catch(()=>{}).then(()=>writeState(snapshot));try{await saveChain;saveFailed=false;updateSaveBadge();}catch(e){saveFailed=true;updateSaveBadge();toast('端末への保存に失敗しました。バックアップを出力してください。');throw e;}finally{pendingSaves--;updateSaveBadge();}}
function updateSaveBadge(){const b=$('#save-status');if(b){b.textContent=readonly?'閲覧専用':pendingSaves?'保存中…':saveFailed?'保存失敗：バックアップしてください':'この端末に保存';b.style.background=saveFailed?'#fde1d7':'';}}
function options(items,value){return items.map(([v,label])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(label)}</option>`).join('');}
function teamOptions(value){return options(state.teams.map(t=>[t.id,t.name]),value);}
function playerOptions(tid,value,empty='未指定'){return options([['',empty],...(team(tid)?.players||[]).map(p=>[p.id,`#${p.number} ${p.name}`])],value);}
function metrics(items){return `<div class="metrics">${items.map(([label,value,hint])=>`<div class="metric"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="hint">${esc(hint||'')}</div></div>`).join('')}</div>`;}
function courtSvg(){return `<svg class="hero-court" viewBox="0 0 180 140" aria-hidden="true"><rect x="8" y="8" width="164" height="124" rx="3" fill="none" stroke="#b6d9bb" stroke-width="1.3"/><path d="M90 8v124M8 40c55 0 55 60 0 60m164-60c-55 0-55 60 0 60" fill="none" stroke="#b6d9bb" stroke-width="1.3"/><circle cx="90" cy="70" r="20" fill="none" stroke="#b6d9bb"/><circle cx="73" cy="48" r="5" fill="#d2e9bc"/><circle cx="118" cy="87" r="5" fill="#d2e9bc"/><circle cx="57" cy="87" r="5" fill="#e7b96d"/><path d="m78 51 35 29" stroke="#d2e9bc" stroke-dasharray="4"/></svg>`;}
function render(){cleanup?.();cleanup=null;root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="icon.svg" alt=""><span class="brand-text">Handball<br>Studio<small>YOUR TEAM, YOUR GAME.</small></span></div><nav class="nav" aria-label="メインメニュー">${Object.entries(viewNames).filter(([v])=>state.sharedPlayerId?v==='analysis':!readonly||['dashboard','matches','analysis','video','tactics'].includes(v)).map(([v,label])=>`<button data-view="${v}" class="${v===view?'active':''}" ${v===view?'aria-current="page"':''}><span class="symbol" aria-hidden="true">${symbols[v]}</span><span class="nav-text">${label}</span></button>`).join('')}</nav><div class="sidebar-footer"><span class="online-dot"></span>PERSONAL WORKSPACE<br>記録から、次の一手へ。<br>v0.1 · 個人用</div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">HANDBALL / PERSONAL STUDIO</div><h1>${viewNames[view]}</h1></div><div class="top-actions"><span class="badge" id="save-status"></span>${readonly?'<button class="btn" id="exit-readonly">自分のアプリに戻る</button>':'<button class="btn primary" id="new-match">＋ 新しい試合</button>'}</div></header><div id="content"></div><p class="footer-note">${readonly?'共有された閲覧専用データを表示しています。':'Handball Studio · データはこの端末のブラウザ内に保存されます。定期的にバックアップしてください。'}<br>iPad Safari実機での操作・録画・保存継続性は検証中です。</p></main></div>`;
  $$('[data-view]').forEach(el=>el.onclick=()=>go(el.dataset.view));$('#new-match')?.addEventListener('click',newMatchDialog);$('#exit-readonly')?.addEventListener('click',()=>location.assign(location.pathname));updateSaveBadge();if(!readonly)void notifyLowStock();
  ({dashboard:renderDashboard,matches:renderMatches,record:renderRecord,analysis:renderAnalysis,video:renderVideo,tactics:renderTactics,roster:renderRoster,inventory:renderInventory,settings:renderSettings}[view])();
}
function go(v){view=v;render();window.scrollTo({top:0,behavior:'instant'});}
function content(html){$('#content').innerHTML=html;}
function selectMatchBar(){return `<div class="toolbar section-gap"><label class="field">対象試合<select id="match-select">${options(state.matches.map(m=>[m.id,matchLabel(m)]),matchId)}</select></label></div>`;}
function bindMatchSelect(){ $('#match-select')?.addEventListener('change',async e=>{matchId=e.target.value;if(!readonly){state.preferences??={};state.preferences.activeMatchId=matchId;await save();}render();});}
function noMatch(){content(`<div class="panel list-empty">まだ試合がありません。<br>${readonly?'':'「新しい試合」から記録を始めてください。'}</div>`);}
function displayMatches(matches){return matches.map(m=>{const h=summarize([m],m.homeTeamId),a=summarize([m],m.awayTeamId);return `<div class="match-row"><div class="date-box">${esc(m.date.slice(8))}<small>${esc(m.date.slice(5,7))}月</small></div><div><strong>${esc(matchLabel(m))}</strong><p>${esc(m.tournament||'練習試合')} · ${activeEvents(m).length}プレー記録 ${m.finished?'· 終了':''}</p></div><button class="btn" data-open-match="${esc(m.id)}"><span class="score">${h.goals}–${a.goals}</span></button></div>`;}).join('')||'<div class="list-empty">該当する試合はありません。</div>';}
function bindMatchLinks(){ $$('[data-open-match]').forEach(el=>el.onclick=()=>{matchId=el.dataset.openMatch;go(readonly?'analysis':'record');});}
function renderDashboard(){teamId??=state.teams[0]?.id;const {matches:relevant,totals:all,recent,wins}=dashboardModel(state,teamId);
content(`${readonly?'':'<section id="start-guide" style="margin-bottom:20px"></section>'}<div class="toolbar" style="margin-bottom:16px"><label class="field">表示チーム<select id="dashboard-team">${teamOptions(teamId)}</select></label></div><section class="hero"><div><div class="eyebrow">EVERY PLAY TELLS A STORY</div><h2>今日の記録を、<br>チームの次の一手に。</h2><p>試合の流れを残し、数字で振り返る。<br>あなたのチームだけのハンドボールノート。</p>${readonly?'':'<button class="btn" id="hero-record">試合を記録する ↗</button>'}</div>${courtSvg()}</section>${metrics([['記録した試合',relevant.length,'選択チームの試合'],['総得点',all.goals,'記録されたシュートから集計'],['シュート成功率',pct(all.shotRate),all.complete.shots?'全シュート記録済み':'未確認の試合を含むため非表示'],['勝利',wins,'終了した試合のみ']])}<div class="grid two dashboard-bottom"><section class="panel"><div class="panel-head"><h2>選択チームの最近の試合</h2><button class="btn small" id="all-matches">すべて見る →</button></div>${displayMatches(recent)}${state.inventory.some(i=>i.quantity<=i.minimum)?`<div class="notice">補充目安の備品：${state.inventory.filter(i=>i.quantity<=i.minimum).length}件</div>`:''}</section><section class="panel"><div class="panel-head"><h2>チームの振り返り</h2><span class="badge">${esc(team(teamId)?.name||'チーム未登録')}</span></div>${phaseBars(relevant,teamId)}<div class="notice">${all.complete.shots?'記録した攻撃形態ごとのシュート傾向です。7mスローは除外しています。':'全シュートの記録確認がまだです。得点だけの記録から成功率は表示しません。'}</div><button class="btn" id="open-analysis">データを詳しく見る →</button></section></div>`);
if(!readonly)cleanup=mountReadiness($('#start-guide'),{state,save,toast,onNavigate:navigateGuide,onSample:openSamples});$('#dashboard-team').onchange=async e=>{teamId=e.target.value;state.preferences??={};state.preferences.teamId=teamId;if(!readonly)await save();render();};$('#hero-record')?.addEventListener('click',()=>state.matches.length?go('record'):newMatchDialog());$('#all-matches').onclick=()=>go('matches');$('#open-analysis').onclick=()=>go('analysis');bindMatchLinks();}
function phaseBars(matches,tid){return attackPhaseModel(matches,tid).map(x=>`<div class="bar-row"><span>${phaseNames[x.phase]}</span><div class="bar-track"><div class="bar-fill" style="width:${x.rate??0}%"></div></div><strong>${pct(x.rate)}</strong></div>`).join('');}
function renderMatches(){content(`<section class="panel"><div class="panel-head"><h2>試合ノート</h2><input id="match-search" type="search" placeholder="対戦相手・大会で検索" aria-label="試合を検索"></div><div id="match-list">${displayMatches([...state.matches].sort((a,b)=>b.date.localeCompare(a.date)))}</div></section>`);bindMatchLinks();$('#match-search').oninput=e=>{$('#match-list').innerHTML=displayMatches(state.matches.filter(m=>(matchLabel(m)+' '+m.tournament).includes(e.target.value)));bindMatchLinks();};}
function openDialog(html,onSubmit){const d=$('#modal');d.innerHTML=html;d.showModal();let busy=false;const preventClose=e=>{if(busy)e.preventDefault();};d.addEventListener('cancel',preventClose);d.addEventListener('close',()=>d.removeEventListener('cancel',preventClose),{once:true});$('[data-close]',d)?.addEventListener('click',()=>{if(!busy)d.close();});$('form',d)?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const data=new FormData(e.target,e.submitter);const controls=$$('button,input,select',d),disabled=controls.map(el=>el.disabled);busy=true;controls.forEach(el=>el.disabled=true);try{await onSubmit(data);d.close();}catch(err){toast(err.message);controls.forEach((el,i)=>el.disabled=disabled[i]);}finally{busy=false;}});}
function newMatchDialog(){if(readonly)return;if(state.teams.length<2){toast('まず自チームと相手チームを登録してください');go('roster');return;}
openDialog(`<h2>新しい試合を作成</h2><form><div class="form-grid"><label class="field">自チーム<select name="home">${teamOptions(teamId||state.teams[0].id)}</select></label><label class="field">相手チーム<select name="away">${teamOptions(state.teams.find(t=>t.id!==teamId)?.id||state.teams[1].id)}</select></label><label class="field">試合日<input name="date" type="date" value="${new Date().toLocaleDateString('sv-SE')}" required></label><label class="field">前後半それぞれの時間（分）<input name="minutes" type="number" min="1" max="60" value="30" required></label><label class="field">大会・リーグ名<input name="tournament" placeholder="例：秋季大会" maxlength="100"></label><label class="field">試合名（任意）<input name="name" maxlength="100"></label></div><div class="dialog-actions"><button type="button" class="btn" data-close>キャンセル</button><button type="submit" class="btn primary">作成して記録へ</button></div></form>`,async f=>{if(f.get('home')===f.get('away'))throw new Error('異なるチームを選択してください');const m=createMatch({homeTeamId:f.get('home'),awayTeamId:f.get('away'),opponent:team(f.get('away')).name,date:f.get('date'),periodMinutes:Number(f.get('minutes')),tournament:f.get('tournament'),name:f.get('name')});m.rosterSnapshots=Object.fromEntries([m.homeTeamId,m.awayTeamId].map(id=>[id,structuredClone(team(id)?.players||[])]));m.rosters=Object.fromEntries([m.homeTeamId,m.awayTeamId].map(id=>[id,(team(id)?.players||[]).map(p=>p.id)]));state.matches.push(m);matchId=m.id;teamId=m.homeTeamId;state.preferences??={};state.preferences.teamId=teamId;state.preferences.activeMatchId=matchId;await save();go('record');});}
function initDraft(m,tid){const key=m.id+tid;if(!draft[key])draft[key]={phase:'set',defense:'6-0',pattern:'',zone:null,position:null,sevenMeter:false,emptyNet:false,shotType:'',subtype:'',missLocation:'',goalkeeperId:team(tid===m.homeTeamId?m.awayTeamId:m.homeTeamId)?.players.find(p=>p.position==='GK')?.id||'',tacticId:''};return draft[key];}
function currentGoalkeeper(m,tid){return m.currentGoalkeepers?.[tid]??team(tid)?.players.find(p=>p.position==='GK'&&!p.archived)?.id??'';}
function recordDetails(m,tid){const d=initDraft(m,tid);return `<details class="details" ${recordMode==='detail'?'open':''}><summary>シュート・戦術の詳細</summary><div class="form-grid"><label class="field">攻撃形態<select data-draft="phase" data-tid="${esc(tid)}">${options(Object.entries(phaseNames),d.phase)}</select></label><label class="field">相手の守備隊形<select data-draft="defense" data-tid="${esc(tid)}">${options(['6-0','5-1','3-2-1','4-2','3-3','マンツーマン','不明'].map(x=>[x,x]),d.defense)}</select></label><label class="field">攻撃パターン<select data-draft="pattern" data-tid="${esc(tid)}">${options([['','未指定'],['cross','クロス'],['parallel','パラレル'],['post','ポスト連携'],['cut','カットイン'],['one','1対1']],d.pattern)}</select></label><label class="field">使用した作戦<select data-draft="tacticId" data-tid="${esc(tid)}">${options([['','未指定'],...state.tactics.map(t=>[t.id,t.name])],d.tacticId)}</select></label><label class="field">シュート種類<select data-draft="shotType" data-tid="${esc(tid)}">${options([['','未指定'],['wing','サイド'],['backcourt','ロング'],['pivot','ポスト'],['breakthrough','カットイン'],['fast','速攻'],['other','その他']],d.shotType)}</select></label><label class="field">ミスの種類<select data-draft="subtype" data-tid="${esc(tid)}">${options([['','未指定'],['pass','パスミス'],['catch','キャッチミス'],['charge','チャージ'],['steps','オーバーステップ'],['dribble','ダブルドリブル'],['passive','パッシブ']],d.subtype)}</select></label><label class="field">失敗した位置<select data-draft="missLocation" data-tid="${esc(tid)}">${options([['','未指定'],['high','上'],['left','左'],['right','右'],['bar','クロスバー']],d.missLocation)}</select></label></div><label class="check section-gap"><input type="checkbox" data-empty="${esc(tid)}" ${d.emptyNet?'checked':''}>エンプティーゴール</label><label class="check section-gap"><input type="checkbox" data-seven="${esc(tid)}" ${d.sevenMeter?'checked':''}>7mスロー</label><p class="muted section-gap">シュート位置（ゴールを上に見てタップ）</p><svg class="mini-court" data-shot-court="${esc(tid)}" viewBox="0 0 300 180" role="img" aria-label="シュート位置を選択"><rect x="3" y="3" width="294" height="174" fill="none" stroke="#91b49b"/><path d="M104 3v8h92V3M40 3a110 110 0 0 0 220 0M15 3a135 135 0 0 0 270 0" fill="none" stroke="#91b49b"/><circle data-shot-marker cx="${d.position?d.position.x*300:-10}" cy="${d.position?d.position.y*180:-10}" r="6" fill="#d38740"/></svg><p class="muted">ゴールコース（シューターから見た9分割）</p><div class="zone-grid">${Array.from({length:9},(_,i)=>`<button data-zone="${i+1}" data-tid="${esc(tid)}" class="${d.zone===i+1?'selected':''}">${i+1}</button>`).join('')}</div><button class="btn small" data-clear-detail="${esc(tid)}">位置・コースを未指定に戻す</button></details>`;}
function recordTeam(m,tid,away){
  const t=team(tid),guided=recordMode==='guided'||recordMode==='official';
  const players=(t?.players||[]).filter(p=>!p.archived&&(!m.rosters?.[tid]||m.rosters[tid].includes(p.id)));
  const primary=guided?[['goal','ゴール','goal'],['shot-miss','シュート✕','miss'],['7m-goal','7m成功','goal'],['7m-miss','7m失敗','miss']]:[['goal','得点','goal'],['saved','セーブされた','save'],['miss','枠外','miss'],['post','ポスト','miss'],['blocked','ブロック','miss']];
  const others=[['turnover','ミス',''],['interception','パスカット',''],['loose_ball','ルーズボール',''],['seven_meter_awarded','7m獲得',''],['warning','警告','penalty'],['suspension','2分退場','penalty'],['disqualification','失格','penalty'],['free_throw_won','FT獲得',''],['free_throw_conceded','FT被獲得',''],['timeout','タイムアウト',''],['substitution','選手交代','']];
  const buttons=list=>list.map(([action,label,cls])=>`<button class="${cls}" data-action="${action}" data-tid="${esc(tid)}">${label}</button>`).join('');
  return `<section class="panel record-team ${away?'away':''}" data-team-panel="${esc(tid)}"><div class="panel-head"><h2>${esc(t?.name||'チーム')}</h2><span class="badge">${away?'AWAY':'HOME'}</span></div><label class="field">守っているGK<select data-own-gk="${esc(tid)}">${playerOptions(tid,currentGoalkeeper(m,tid),'GK未指定')}</select></label><p class="record-hint">① 選手を選ぶ（未指定でも記録できます）</p><div class="players">${players.map(p=>`<button class="player ${selection[tid]?.id===p.id?'selected':''}" data-player="${esc(p.id)}" data-tid="${esc(tid)}" aria-pressed="${selection[tid]?.id===p.id}"><strong>${esc(p.number)}</strong><small>${esc(p.name)}</small></button>`).join('')}<button class="player ${selection[tid]?.id==null?'selected':''}" data-player="" data-tid="${esc(tid)}"><strong>—</strong><small>未指定</small></button></div><p class="record-hint">② プレーを押す${guided?' → コース → 位置の順に入力':''}</p><div class="action-grid shot-actions">${buttons(primary)}</div><details class="details other-actions" ${recordMode==='detail'?'open':''}><summary>ミス・反則・その他の記録</summary><div class="action-grid">${buttons(others)}</div></details>${ownOnly&&!away?`<section class="defense-actions"><h3>守備：相手が打ったシュート</h3><p class="muted">上で選んだ自チームGKの成績に記録します。</p><div class="action-grid"><button class="penalty" data-defense-action="goal">失点<small>決められた</small></button><button class="save" data-defense-action="saved">セーブ<small>止めた</small></button><button class="miss" data-defense-action="miss">枠外<small>外れた</small></button><button data-defense-action="gk-7m">ペナ<small>7mスロー</small></button></div></section>`:''}${guided?'':recordDetails(m,tid)}</section>`;
}
