$$('[data-player]').forEach(b=>b.onclick=()=>{const tid=b.dataset.tid;const vc=videoDock?cleanup?.getClock?.():null;selection[tid]={id:b.dataset.player||null,clockMs:vc?.clockMs??clockMs(currentMatch()),at:Date.now(),period:vc?.period??currentMatch().period};$$(`[data-player][data-tid="${tid}"]`).forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b?'true':'false');});});
