async function commitRecord(mid,event,{message,clearTeam,displayTeamId=event.teamId}={}){
  const latest=state.matches.find(x=>x.id===mid);if(!latest)throw new Error('この試合は見つかりません。記録を確定できませんでした');
  if(latest.finished)throw new Error('終了済みの試合です。試合設定を確認してください');
  const already=latest.events.some(x=>x.id===event.id),wasRunning=latest.clock;
  if(!already){let next=addEvent(latest,event);if(event.type==='timeout')next.clock={elapsed:clockMs(next),runningSince:null};replaceMatch(next);}
  const staged=state.matches.find(x=>x.id===mid),stagedEvent=JSON.stringify(staged.events.find(x=>x.id===event.id)),stagedClock=JSON.stringify(staged.clock);
  try{await save();}catch(error){const current=state.matches.find(x=>x.id===mid);if(!already&&current&&JSON.stringify(current.events.find(x=>x.id===event.id))===stagedEvent)replaceMatch({...current,events:current.events.filter(x=>x.id!==event.id),...(event.type==='timeout'&&JSON.stringify(current.clock)===stagedClock?{clock:wasRunning}:{})});throw error;}
  if(!undoStack.some(x=>x.eventId===event.id))undoStack.push({matchId:mid,eventId:event.id});
  if(clearTeam){delete selection[clearTeam];$$('[data-player]').filter(el=>el.dataset.tid===clearTeam).forEach(el=>{const selected=!el.dataset.player;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});}
  playFeedback(event.type==='shot'&&event.result==='goal'?'goal':['warning','suspension','disqualification'].includes(event.type)?'penalty':'record');toast(`${team(displayTeamId)?.name||''} · ${message||'プレー'}を記録しました`);
  if(videoDock)refreshRecord();else render();
}
