function substitutionDialog(m,tid){openDialog(`<h2>選手交代 · ${esc(team(tid)?.name)}</h2><form><label class="field">退く選手<select name="out">${playerOptions(tid,'')}</select></label><label class="field">入る選手<select name="in">${playerOptions(tid,'')}</select></label><div class="dialog-actions"><button type="button" class="btn" data-close>キャンセル</button><button type="submit" class="btn primary">交代を記録</button></div></form>`,async f=>{if(!f.get('in')||f.get('in')===f.get('out'))throw new Error('入る選手と退く選手を確認してください');replaceMatch(addEvent(m,{teamId:tid,type:'substitution',playerId:f.get('in'),outPlayerId:f.get('out')}));await save();render();});}
